<div class="page-head"><div><span class="eyebrow">Super Admin</span><h1>Platform Overview</h1><p>Manage businesses, users, and reporting activity.</p></div><a class="btn btn-primary" href="<?=url('admin-business-form')?>">+ Add Business</a></div><div class="kpi-grid four"><article class="kpi-card"><small>Active Businesses</small><strong><?=numfmt($counts['businesses'])?></strong></article><article class="kpi-card"><small>Business Users</small><strong><?=numfmt($counts['users'])?></strong></article><article class="kpi-card"><small>Completed Reports</small><strong><?=numfmt($counts['reports'])?></strong></article><article class="kpi-card"><small>Failed Batches</small><strong><?=numfmt($counts['failed'])?></strong></article></div><section class="panel"><div class="panel-head"><h2>Recent Upload Activity</h2><a href="<?=url('admin-uploads')?>">View all</a></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>Period</th><th>Status</th><th>Uploaded by</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['business_name'])?></td><td><?=e(reporting_us_date($r['period_start']))?> → <?=e(reporting_us_date($r['period_end']))?></td><td><span class="status status-<?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?=e($r['uploaded_by_name'])?></td><td><?=e(reporting_us_date($r['created_at'],true))?></td><td><?php if($r['status']==='completed'):?><form method="post" action="<?=url('admin-business-view')?>" class="inline-action-form"><?=csrf_field()?><input type="hidden" name="business_id" value="<?=e($r['business_id'])?>"><input type="hidden" name="destination" value="report"><input type="hidden" name="resource_id" value="<?=e($r['id'])?>"><button class="link-button" type="submit">View</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6" class="empty-cell">No reports yet.</td></tr><?php endif;?></tbody></table></div></section>
